/**
 * Shape of json/arts-costs.json, generated by tools-js/build-arts-costs.cjs
 * from the game's master data. Weapon "Arts Lv." (`slv`) upgrade cost.
 */
declare interface ArtsMaterial {
  mst_material_id: number;
  amount: number;
}

declare interface ArtsCostRow {
  /** Materials spent per composite step. */
  materials: ArtsMaterial[];
  /** Arts levels covered by one composite (`bugiStrengthenNeedMaterialTable.mCommonUpNum`). */
  commonUpNum: number;
}

declare interface ArtsCosts {
  _comment: string;
  _source: { materials: string; zeny: string; weaponSeries: string[] };
  /** rarity -> flat zeny base. */
  zenyByRarity: Record<string, number>;
  /** kariwaza hash -> its cost row. */
  byKariwaza: Record<string, ArtsCostRow>;
  /** mst_equipment_id -> kariwaza hash (only weapons that have an arts cost). */
  kariwazaByEquipment: Record<string, number>;
}

declare const ARTS: ArtsCosts;
export default ARTS;
